# -*- coding: utf-8 -*-
import importlib.util, os
spec=importlib.util.spec_from_file_location("c","/tmp/wk4common.py"); c=importlib.util.module_from_spec(spec); spec.loader.exec_module(c)
P,new_doc=c.P,c.new_doc
from docx.shared import RGBColor
ACCENT=RGBColor(0x1F,0x4E,0x79); GREY=RGBColor(0x55,0x55,0x55); CUE=RGBColor(0x8A,0x4B,0x08)
WK="/sessions/kind-compassionate-feynman/mnt/RootCourse/week04"
d=new_doc("Week 4 — Instructor Script (v1)")
P(d,[("Week 4 — Instructor Lecture Script (Co-occurrence)",True)],size=18,after=2,color=ACCENT)
P(d,"Spoken script, ~45 minutes, eight modules. Our first PAIR measure and first FIND task. Worked target صلو (prayer). Scope: observed-vs-expected (a first, frequency-based control); the length-aware null, Monte-Carlo, and lift TIERS are Week 5. ▸ lines are delivery cues. Every value computed from Book6.",size=9.5,after=8,color=GREY)
def marker(t,title): P(d,[(t+"  ",True),(title,True)],size=12,before=10,after=3,color=ACCENT)
def cue(t): P(d,[("▸ "+t,False)],size=9.5,after=3,color=CUE)
def say(t): P(d,t,size=11,after=5)

marker("0:00","Module 1 · From one root to a pair")
cue("Slides 1–2.")
say("For three weeks we have studied single roots — how often one is named, where it sits, what shapes it wears, what company it keeps. Today we change the unit. We put two roots side by side and ask the simplest possible question about their relationship: how often do they appear in the same ayah? That is co-occurrence, and it is the first step from describing words to mapping the structure that ties them together. And we turn it into a contest — a find task: given a target root and a handful of candidates, which candidate really shares the most with the target? Our target today is prayer, صلو. By the end of the hour you will know its closest companion in the whole Qur'an — and I promise you it is not the one the obvious count nominates.")
marker("5:00","Module 2 · Counting shared ayahs")
cue("Slide 3 — the overlap.")
say("Start with the raw ingredient. The joint count of two roots is just the number of ayahs that contain both — the overlap of two circles. Prayer appears in ninety ayahs; zakat, almsgiving, in fifty-six; and twenty-eight ayahs name both. Notice how blunt this is: we don't care where in the verse the two roots sit or how they're related grammatically, only that both are present. It is the crudest possible notion of togetherness, and we will sharpen it. But first, the count itself: prayer shares fifty-two ayahs with قوم, establish, forty-four with God, twenty-eight with zakat. On the raw count, “establish” and “God” lead, and charity trails in third.")
marker("11:00","Module 3 · Why the raw count misleads")
cue("Slide 5. Tell the celebrity story.")
say("Here is why that raw ranking is a trap, and it's the same trap as Week 2's length confound wearing new clothes. Picture a celebrity who turns up at every event in town. Flip through the year's photographs and you'll find hundreds of the celebrity standing next to your friend — not because they're close, but because the celebrity is in every single photo. Now picture an ordinary person who appears in only fifty photos all year, and your friend is in twenty-eight of them. That second number is a relationship; the first is just ubiquity. God, ءله, is the celebrity of this corpus — named in one thousand eight hundred and seventy-nine ayahs, more than a quarter of the book — so of course it shares forty-four with prayer; it shares dozens with nearly everything. Zakat appears in only fifty-six ayahs in the whole Qur'an, and twenty-eight of them — half — are with prayer. The small number is the loud one. So the raw ranking measures a candidate's fame at least as much as its bond, and that makes it nearly useless for telling pairs apart.")
marker("18:00","Module 4 · Observed vs expected")
cue("Slide 6 — the bars.")
say("The fix is to compare what we observed to what we'd expect by pure chance. If two roots were just sprinkled through the book independently, with no bond at all, how many ayahs would they share? That's easy to compute: multiply the two frequencies and scale to the corpus — frequency of the target times frequency of the candidate, divided by six thousand two hundred and thirty-six. For prayer and God: ninety times eighteen seventy-nine over six-two-three-six is about twenty-seven — so we'd expect about twenty-seven shared ayahs from two roots that common even if nothing tied them, and we see forty-four, only a little more. For prayer and zakat: ninety times fifty-six over six-two-three-six is about zero point eight expected — and we see twenty-eight. Then the measure is simply how many times observed beats expected. Think of a crowded reception where everyone mills at random: two guests who keep ending up in the same corner far more often than random milling would predict are clearly seeking each other out — and the rarer the guest, the more telling it is.")
marker("25:00","Module 5 · The headline & the unlearn")
cue("Slides 7–8 — controlled ranking, then the flip.")
say("Now watch the picture flip. God's forty-four shared ayahs are only about one-point-six times chance — the background hum of a root that's everywhere. قوم falls to six times. And zakat's twenty-eight, against an expectation below one, stands at thirty-four-point-six times chance. The candidate that was third on the raw list is first by a landslide. And this isn't a quirk — it's one of the Qur'an's signature pairings: أقيموا الصلاة وآتوا الزكاة, establish prayer and give zakat. Of all fifty-six ayahs that mention almsgiving anywhere, twenty-eight — exactly half — name prayer in the same breath. The bond a careful reader feels is now a measured fact. But only the controlled measure could see it, because zakat is simply too rare to win a raw shouting match against God and “establish.” The unlearn: prayer's closest companion is not establishment or even God — those merely sit near everything — it is charity.")
marker("32:00","Module 6 · The find-task")
cue("Slides 9–11.")
say("So here is the skill each of you will practise. Given a target and a slate of candidates, compute each candidate's times-over-chance; throw out any pair with fewer than five shared ayahs, because two or three overlaps are too little to trust — the same small-sample caution as Week 2's support floor; and read the top of the controlled list, never the raw list. Rank by surprise, not by size. And the method generalises beautifully. Measure and weight, كيل and وزن, share only six ayahs — but at one hundred and thirty-seven times chance: the Qur'an's warning to those who give short measure and short weight in the marketplace. Covenant bonds to breaking, عهد and نقض, at ninety-six times — the text speaks of the covenant chiefly to condemn its breach. Prostration to bowing, the two postures of the prayer, at forty-six. In every case, a rare and specific pair the raw count would have buried under God and “say.”")
marker("38:00","Module 7 · Limits & clusters")
cue("Slides 12–13.")
say("Be honest about what this measure still can't do. First, our control is deliberately rough: it divides out each candidate's frequency, but it still ignores ayah length — and a long verse packed with twenty roots hands out co-occurrences far more freely than a three-root verse. That's the length confound again, waiting one level down, and next week we fix it with a length-aware null model, check it by running thousands of shuffled simulations, and only then sort pairs into tiers of real, borderline, and spurious. Second, co-occurrence is symmetric: it tells you prayer and zakat travel together, but not whether mentioning one pulls in the other — that direction is Week 6. Third, and say this aloud, association is not cause and not even agreement: two roots can share verses because the text praises them together or because it contrasts them, exactly as we saw with antonym partners last week. One happier note: co-occurrence also reveals whole clusters, not just pairs. Paradise, جنن, lights up with Eden, with the rivers that flow beneath, تحت and جري, and with eternity — a constellation the measure shows you all at once.")
marker("43:00","Module 8 · Fact vs interpretation, wrap & bridge")
cue("Slides 14–15.")
say("Let me model the discipline one more time, because co-occurrence is where it's most tempting to break — the bonds are so evocative that the number feels like it already contains the sermon. Fact: of zakat's fifty-six ayahs, twenty-eight are shared with prayer, thirty-four-point-six times the chance rate, the highest controlled bond on prayer's slate. Interpretation, clearly labelled: I read prayer and charity as a single act of devotion with two faces, one turned toward God and one toward people. One sentence the corpus forces on anyone who counts; one sentence that is mine. For the exercise: take your assigned target and its candidate slate, compute each candidate's times-over-chance, name the controlled winner, and write one fact and one labelled interpretation about the bond you found. To close: frequency told us how much, distribution where, forms and partners what-shape and who-with — and co-occurrence now measures who-with, fairly, by asking not how many shared but how many more than chance. Next week we make that trust rigorous: a pair's lift, a length-aware null tested by simulation, and the tiers that tell us which bonds are real. See you then.")
d.save(os.path.join(WK,"Week4_Instructor_Script.docx")); print("script saved | words:",sum(len(p.text.split()) for p in d.paragraphs))
